<?php $title='Serviços e preços'; ?>
<div class="dashboard-grid two"><section class="panel-card"><h2>Novo serviço</h2><form method="post" action="<?=url('/partner/services')?>"><?=csrf_field()?><label>Nome<input name="name" required></label><label>Categoria<input name="category" placeholder="Consulta, banho, diária..."></label><label>Descrição<textarea name="description" rows="4"></textarea></label><div class="form-grid"><label>Preço (R$)<input type="number" step="0.01" name="price" value="0"></label><label>Duração em minutos<input type="number" name="duration_minutes" value="60"></label></div><label class="check"><input type="checkbox" name="active" value="1" checked> Serviço ativo</label><button class="btn btn-primary btn-block">Publicar serviço</button></form></section><section class="panel-card"><h2>Serviços publicados</h2><?php foreach($services as $service):?><div class="service-admin"><div><b><?=e($service['name'])?></b><p><?=e($service['description'])?></p><small><?=e($service['category'])?> · <?=e($service['duration_minutes'])?> min</small></div><strong><?=money($service['price_cents'])?></strong></div><?php endforeach;?></section></div>
